import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load and apply background texture
  const textureAsset = ctx.textureLoader.load(config.assets.imageUrl);
  const geometry = new THREE.PlaneGeometry(1.6, 1.0);
  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(textureAsset);
  material.transparent = true;
  material.side = THREE.DoubleSide;

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content
  if (config.textContent && config.textContent.length > 0) {
    for (const textItem of config.textContent) {
      const textContent = typeof textItem === 'string' ? textItem : textItem.text;

      const textMesh = ctx.fontAtlas.render(textContent, {
        font: 'Lora',
        size: 0.34,
        weight: 400,
        color: 0x16161d,
        align: 'center'
      });

      if (textMesh) {
        textMesh.position.z = 0.01;
        group.add(textMesh);
      }
    }
  }

  // Apply scene position
  if (config.scenePosition) {
    group.position.set(
      config.scenePosition.x ?? 0,
      config.scenePosition.y ?? 0,
      config.scenePosition.z ?? 0
    );
  }

  // Billboard toward camera
  group.rotation.y = Math.PI;

  // Apply scale
  if (config.scale) {
    group.scale.set(
      config.scale.x ?? 1,
      config.scale.y ?? 1,
      config.scale.z ?? 1
    );
  }

  // Setup cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureAsset.dispose();
  };

  return group;
}
